// Choose the nicest available English voice (falls back to any en voice).
function pickEnglishVoice(voices) {
  if (!voices || !voices.length) return null;
  const en = voices.filter((v) => /^en(-|_|$)/i.test(v.lang));
  if (!en.length) return null;
  const preferred = ["Google US English", "Samantha", "Microsoft Aria", "Microsoft Zira"];
  for (const name of preferred) {
    const m = en.find((v) => v.name === name);
    if (m) return m;
  }
  return en.find((v) => /en-US/i.test(v.lang)) || en[0];
}

