// =================================================================
// Flashcard
// =================================================================
function Flashcard({ data, mastered, onMaster, onNotSure }) {
  const [showMeaning, setShowMeaning] = useState(false);
  const [isPast, setIsPast] = useState(false);
  const [ripple, setRipple] = useState(false);
  const [shake, setShake] = useState(false);
  const [speaking, setSpeaking] = useState(false);
  const [speakMode, setSpeakMode] = useState(null); // 'normal' | 'slow' | null
  const rippleTimer = useRef(null);

  const t = THEMES[data.theme];
  const phrase = isPast ? data.past : data.base;

  function playAudio(rate = 0.85) {
    const mode = rate <= 0.6 ? "slow" : "normal";
    // ripple effect (restart cleanly)
    setRipple(false);
    window.requestAnimationFrame(() => setRipple(true));
    clearTimeout(rippleTimer.current);
    rippleTimer.current = setTimeout(() => setRipple(false), 750);

    // real pronunciation via Web Speech API
    if (typeof window === "undefined" || !window.speechSynthesis) return;
    const synth = window.speechSynthesis;
    synth.cancel(); // stop anything already playing
    const u = new SpeechSynthesisUtterance(phrase);
    u.lang = "en-US";
    u.rate = rate; // 0.85 = gentle, 0.55 = slow practice pace
    u.pitch = 1.05;
    const voice = pickEnglishVoice(synth.getVoices());
    if (voice) u.voice = voice;
    u.onstart = () => { setSpeaking(true); setSpeakMode(mode); };
    u.onend = () => { setSpeaking(false); setSpeakMode(null); };
    u.onerror = () => { setSpeaking(false); setSpeakMode(null); };
    synth.speak(u);
  }

  function handleNotSure() {
    setShake(true);
    setTimeout(() => setShake(false), 460);
    onNotSure(data.id);
  }

  useEffect(() => {
    return () => {
      clearTimeout(rippleTimer.current);
      if (typeof window !== "undefined" && window.speechSynthesis) {
        window.speechSynthesis.cancel();
      }
    };
  }, []);

  // Past-tense "shape-shift" overrides the header gradient with an energetic scheme.
  const headerGrad = isPast ? "from-orange-500 to-purple-600" : t.grad;

  return (
    <div
      className={[
        "relative overflow-hidden rounded-3xl bg-white shadow-lg",
        "transition-all duration-500",
        mastered ? "ring-4 ring-green-400 shadow-green-200" : "ring-1 ring-slate-100",
        shake ? "ac-shake" : "",
        isPast ? "-rotate-1" : "rotate-0",
      ].join(" ")}
    >
      {/* audio ripple layer */}
      {ripple && (
        <span className="pointer-events-none absolute left-1/2 top-16 z-20 -ml-12 -mt-12 h-24 w-24 rounded-full bg-yellow-300 ac-ripple" />
      )}

      {/* mastered check badge */}
      {mastered && (
        <div className="absolute right-2 top-2 z-30 flex h-9 w-9 items-center justify-center rounded-full bg-green-500 text-white shadow-md ac-pop">
          <Check size={20} strokeWidth={3} />
        </div>
      )}

      {/* Header: framed illustration on a colored gradient strip */}
      <div className={`relative flex items-center justify-center bg-gradient-to-br ${headerGrad} py-3 transition-all duration-500`}>
        <div className={`h-16 w-28 overflow-hidden rounded-2xl bg-white shadow-inner ring-4 ${isPast ? "ring-orange-200" : t.ring}`}>
          <VocabArt id={data.id} />
        </div>
        {isPast && (
          <span className="absolute right-3 top-3 rounded-full bg-white/90 px-2 py-0.5 text-xs font-extrabold text-purple-700 shadow">
            PAST ⏳
          </span>
        )}
      </div>

      {/* Body */}
      <div className="px-3 pb-3 pt-3">
        {/* Phrase – re-keyed so it fades on every tense switch */}
        <p
          key={phrase}
          className={`ac-fade min-h-12 text-center text-lg font-extrabold leading-tight ${isPast ? "text-purple-700" : "text-slate-800"}`}
        >
          {phrase}
        </p>

        {/* Meaning reveal */}
        <div className="mt-1 min-h-7 text-center">
          {showMeaning ? (
            <p className={`ac-fade rounded-xl px-2 py-1 text-sm font-bold ${t.soft} ${t.softText}`}>
              {data.vi}
            </p>
          ) : (
            <span className="text-sm text-slate-300">• • •</span>
          )}
        </div>

        {/* Mini controls — row 1: meaning + tense */}
        <div className="mt-2 grid grid-cols-2 gap-1.5">
          <button
            onClick={() => setShowMeaning((v) => !v)}
            className="flex items-center justify-center gap-1 rounded-2xl bg-slate-100 py-2 text-slate-600 transition-all duration-200 hover:scale-105 hover:bg-slate-200 active:scale-95"
          >
            {showMeaning ? <EyeOff size={16} /> : <Eye size={16} />}
            <span className="text-[11px] font-bold leading-none">{showMeaning ? "Hide" : "Meaning"}</span>
          </button>

          <button
            onClick={() => setIsPast((v) => !v)}
            className={[
              "flex items-center justify-center gap-1 rounded-2xl py-2 transition-all duration-200 hover:scale-105 active:scale-95",
              isPast ? "bg-purple-500 text-white" : "bg-orange-100 text-orange-600 hover:bg-orange-200",
            ].join(" ")}
          >
            <Hourglass size={16} />
            <span className="text-[11px] font-bold leading-none">Past ⏳</span>
          </button>
        </div>

        {/* Mini controls — row 2: listen + slow practice */}
        <div className="mt-1.5 grid grid-cols-2 gap-1.5">
          <button
            onClick={() => playAudio(0.85)}
            className={[
              "flex items-center justify-center gap-1 rounded-2xl py-2 transition-all duration-200 hover:scale-105 active:scale-95",
              speakMode === "normal" ? "bg-sky-500 text-white" : "bg-sky-100 text-sky-600 hover:bg-sky-200",
            ].join(" ")}
          >
            <Volume2 size={16} className={speakMode === "normal" ? "ac-pop" : ""} />
            <span className="text-[11px] font-bold leading-none">{speakMode === "normal" ? "Speaking" : "Listen"}</span>
          </button>

          <button
            onClick={() => playAudio(0.55)}
            className={[
              "flex items-center justify-center gap-1 rounded-2xl py-2 transition-all duration-200 hover:scale-105 active:scale-95",
              speakMode === "slow" ? "bg-teal-500 text-white" : "bg-teal-100 text-teal-600 hover:bg-teal-200",
            ].join(" ")}
          >
            <span className={`text-base leading-none ${speakMode === "slow" ? "ac-pop" : ""}`}>🐢</span>
            <span className="text-[11px] font-bold leading-none">{speakMode === "slow" ? "Slowly…" : "Slow"}</span>
          </button>
        </div>

        {/* Bottom actions */}
        <div className="mt-2 grid grid-cols-2 gap-1.5">
          <button
            onClick={handleNotSure}
            className="flex items-center justify-center gap-1 rounded-2xl bg-red-50 py-2 text-sm font-extrabold text-red-500 transition-all duration-200 hover:scale-105 hover:bg-red-100 active:scale-95"
          >
            <X size={16} strokeWidth={3} /> Not sure
          </button>
          <button
            onClick={() => onMaster(data.id)}
            className={[
              "flex items-center justify-center gap-1 rounded-2xl py-2 text-sm font-extrabold transition-all duration-200 hover:scale-105 active:scale-95",
              mastered ? "bg-green-500 text-white shadow-md shadow-green-200" : "bg-green-100 text-green-600 hover:bg-green-200",
            ].join(" ")}
          >
            <PartyPopper size={16} /> {mastered ? "Mastered" : "Master"}
          </button>
        </div>
      </div>
    </div>
  );
}

