const LEVEL_UNLOCK_MAP = {
  level_5: new Set([1, 2, 3, 4, 5, 6, 8]),
  level_3: new Set([4, 5]),
};

function UnitGalaxy({ onEnterUnit, onBackToLevels, selectedLevel = "level_5" }) {
  const [toast, setToast] = useState(null);
  const timer = useRef(null);
  const unlockedSet = LEVEL_UNLOCK_MAP[selectedLevel] || LEVEL_UNLOCK_MAP.level_5;
  const units = UNITS.map((u) => ({ ...u, unlocked: unlockedSet.has(u.n) }));
  function tap(u) {
    if (u.unlocked) { onEnterUnit(u.n); return; }
    setToast(`Mission locked! Complete earlier units first! ☄️`);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => setToast(null), 1800);
  }
  useEffect(() => () => clearTimeout(timer.current), []);
  const levelLabel = selectedLevel === "level_3" ? "Galaxy Level 3" : "Galaxy Level 5";
  return (
    <div className="ac-fade">
      <button
        onClick={onBackToLevels}
        className="mb-3 inline-flex items-center gap-2 rounded-full gx-glass px-3 py-1.5 text-xs font-black text-white transition hover:scale-105 active:scale-95"
        style={{ boxShadow:"0 0 14px #22d3ee66, inset 0 0 0 1px #22d3ee55" }}
      >
        🛸 Warp Back to Levels
      </button>
      <div className="px-1 pb-4 pt-1 text-center">
        <h1 className="text-2xl font-black text-white gx-neon-text" style={{ color:"#a5f3fc" }}>🌌 The Solar Matrix</h1>
        <p className="mt-1 text-xs font-bold text-indigo-200">{levelLabel} · Tap a glowing world to begin</p>
      </div>


      <div className="grid grid-cols-2 gap-4 px-1">
        {UNITS.map((u) => (
          <button
            key={u.n}
            onClick={() => tap(u)}
            className="group relative flex flex-col items-center rounded-2xl gx-glass p-3 transition-transform active:scale-95 hover:scale-[1.04]"
            style={{ boxShadow: u.unlocked ? `0 0 22px ${u.glow}66, inset 0 0 0 1px ${u.glow}55` : "inset 0 0 0 1px rgba(255,255,255,.08)" }}
            aria-label={`Unit ${u.n}: ${u.title}${u.unlocked ? "" : " (locked)"}`}
          >
            {/* Planet */}
            <div className="relative my-2 h-20 w-20 gx-bob" style={{ animationDelay: `${u.n * 0.25}s` }}>
              {/* Orbit ring */}
              <div
                className="absolute inset-[-8px] rounded-full gx-spin-slow"
                style={{
                  border: `2px dashed ${u.ring}99`,
                  opacity: u.unlocked ? 0.9 : 0.35,
                  filter: `drop-shadow(0 0 6px ${u.glow}aa)`,
                }}
              />
              {/* Core planet */}
              <div
                className="absolute inset-0 rounded-full"
                style={{
                  background: u.core,
                  boxShadow: u.unlocked
                    ? `0 0 26px ${u.glow}cc, inset -6px -8px 14px rgba(0,0,0,.45)`
                    : `0 0 12px rgba(255,255,255,.12), inset -6px -8px 14px rgba(0,0,0,.55)`,
                  filter: u.unlocked ? "none" : "grayscale(.55) brightness(.7)",
                }}
              />
              {/* Tiny moon */}
              <div
                className="absolute -right-1 -top-1 h-3 w-3 rounded-full"
                style={{ background:"#fff", boxShadow:`0 0 8px ${u.glow}` }}
              />
              {/* Pulse on hover (group) */}
              <div
                className="absolute inset-[-4px] rounded-full opacity-0 transition-opacity duration-300 group-hover:opacity-100"
                style={{ boxShadow:`0 0 0 4px ${u.glow}55, 0 0 28px ${u.glow}` }}
              />
              {/* Lock badge */}
              {!u.unlocked && (
                <div className="absolute inset-0 flex items-center justify-center">
                  <span className="rounded-full bg-black/60 px-2 py-0.5 text-base ring-1 ring-white/30">🔒</span>
                </div>
              )}
              {/* Emoji label floats next to planet */}
              <div className="pointer-events-none absolute -bottom-2 -left-2 text-lg drop-shadow">{u.emoji}</div>
            </div>
            <div className="mt-1 w-full text-center">
              <p className="text-[11px] font-extrabold tracking-wide" style={{ color: u.unlocked ? u.glow : "#94a3b8" }}>UNIT {u.n}</p>
              <p className="truncate text-sm font-black text-white gx-neon-text" style={{ color: u.unlocked ? "#fff" : "#cbd5e1" }}>{u.title}</p>
            </div>
          </button>
        ))}
      </div>
      {toast && (
        <div className="pointer-events-none fixed inset-x-0 bottom-8 z-50 flex justify-center px-4">
          <div className="ac-fade rounded-full gx-glass px-4 py-2 text-sm font-black text-white shadow-2xl"
            style={{ boxShadow:"0 0 18px #a78bfa, inset 0 0 0 1px #a78bfa66" }}>
            {toast}
          </div>
        </div>
      )}
    </div>
  );
}

// =================================================================
// Cosmic chiptune background music (Web Audio API, no deps)
// Upbeat, kid-friendly 8-bit loop for Tier 1 / Tier 2 screens.
// =================================================================
function useCosmicMusic(enabled) {
  useEffect(() => {
    if (!enabled) return;
    if (typeof window === "undefined") return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;

    let cancelled = false;
    let started = false;
    let timers = [];
    let ctx = null;
    let masterGain = null;

    const start = async () => {
      if (started || cancelled) return;
      const tentativeCtx = new AC();
      try { if (tentativeCtx.state === "suspended") await tentativeCtx.resume(); } catch {}
      if (cancelled) { try { tentativeCtx.close(); } catch {} ; return; }
      // If browser still blocked us (no user gesture yet), discard and wait for one.
      if (tentativeCtx.state !== "running") {
        try { tentativeCtx.close(); } catch {}
        return;
      }
      started = true;
      ctx = tentativeCtx;

      masterGain = ctx.createGain();
      masterGain.gain.value = 0;
      masterGain.gain.linearRampToValueAtTime(0.18, ctx.currentTime + 0.6);
      masterGain.connect(ctx.destination);

      const M = { C4:261.63, D4:293.66, E4:329.63, G4:392.0, A4:440.0, C5:523.25, D5:587.33, E5:659.25, G5:783.99,
                  C3:130.81, G3:196.0, A3:220.0, F3:174.61 };
      const melody = [
        M.C5, M.E5, M.G5, M.E5, M.C5, M.E5, M.G5, M.C5,
        M.A4, M.C5, M.E5, M.C5, M.A4, M.C5, M.E5, M.A4,
        M.G4, M.C5, M.E5, M.C5, M.G4, M.D5, M.G5, M.D5,
        M.C5, M.G4, M.E4, M.G4, M.C5, M.E5, M.G5, M.C5,
      ];
      const bass = [M.C3, M.G3, M.A3, M.F3];
      const stepDur = 0.18;
      const loopDur = melody.length * stepDur;

      const playNote = (freq, t, dur, type = "square", vol = 0.22) => {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        o.type = type;
        o.frequency.setValueAtTime(freq, t);
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        o.connect(g).connect(masterGain);
        o.start(t);
        o.stop(t + dur + 0.02);
      };
      const playKick = (t) => {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        o.type = "sine";
        o.frequency.setValueAtTime(120, t);
        o.frequency.exponentialRampToValueAtTime(40, t + 0.18);
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(0.35, t + 0.005);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 0.22);
        o.connect(g).connect(masterGain);
        o.start(t); o.stop(t + 0.25);
      };
      const scheduleLoop = (startAt) => {
        for (let i = 0; i < melody.length; i++) {
          const t = startAt + i * stepDur;
          playNote(melody[i], t, stepDur * 0.9, "square", 0.16);
          if (i % 2 === 0) playNote(bass[(i / 2) % bass.length], t, stepDur * 1.6, "triangle", 0.22);
          if (i % 4 === 0) playKick(t);
        }
      };

      let nextStart = ctx.currentTime + 0.1;
      scheduleLoop(nextStart);
      const tick = () => {
        if (cancelled) return;
        nextStart += loopDur;
        scheduleLoop(nextStart);
        timers.push(setTimeout(tick, loopDur * 1000 - 150));
      };
      timers.push(setTimeout(tick, loopDur * 1000 - 150));
    };

    const onGesture = () => { start(); };
    start();
    window.addEventListener("pointerdown", onGesture);
    window.addEventListener("keydown", onGesture);
    window.addEventListener("touchstart", onGesture, { passive: true });

    return () => {
      cancelled = true;
      window.removeEventListener("pointerdown", onGesture);
      window.removeEventListener("keydown", onGesture);
      window.removeEventListener("touchstart", onGesture);
      timers.forEach(clearTimeout);
      timers = [];
      if (ctx) {
        try {
          if (masterGain) {
            masterGain.gain.cancelScheduledValues(ctx.currentTime);
            masterGain.gain.setValueAtTime(0.0001, ctx.currentTime);
          }
        } catch {}
        setTimeout(() => { try { ctx.close(); } catch {} }, 50);
      }
    };
  }, [enabled]);
}

// =================================================================
// Arcade dance music — energetic loop for game arenas (quiz + grammar)
// =================================================================
function useArcadeMusic(enabled) {
  useEffect(() => {
    if (!enabled) return;
    if (typeof window === "undefined") return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;

    let cancelled = false;
    let started = false;
    let timers = [];
    let ctx = null;
    let masterGain = null;

    const start = async () => {
      if (started || cancelled) return;
      const tentativeCtx = new AC();
      try { if (tentativeCtx.state === "suspended") await tentativeCtx.resume(); } catch {}
      if (cancelled) { try { tentativeCtx.close(); } catch {} ; return; }
      if (tentativeCtx.state !== "running") { try { tentativeCtx.close(); } catch {} ; return; }
      started = true;
      ctx = tentativeCtx;

      masterGain = ctx.createGain();
      masterGain.gain.value = 0;
      masterGain.gain.linearRampToValueAtTime(0.18, ctx.currentTime + 0.5);
      masterGain.connect(ctx.destination);

      const M = {
        C3:130.81, D3:146.83, E3:164.81, F3:174.61, G3:196.00, A3:220.00, B3:246.94,
        C4:261.63, D4:293.66, E4:329.63, F4:349.23, G4:392.00, A4:440.00, B4:493.88,
        C5:523.25, D5:587.33, E5:659.25, F5:698.46, G5:783.99, A5:880.00, B5:987.77,
        C6:1046.5,
      };
      // vi–IV–I–V in C (Am, F, C, G) — climbing arpeggios for excitement
      const melody = [
        M.A4, M.C5, M.E5, M.A5, M.E5, M.C5, M.A4, M.E5,
        M.F4, M.A4, M.C5, M.F5, M.C5, M.A4, M.F4, M.C5,
        M.C5, M.E5, M.G5, M.C6, M.G5, M.E5, M.C5, M.G5,
        M.G4, M.B4, M.D5, M.G5, M.D5, M.B4, M.G4, M.B4,
      ];
      const bass = [
        M.A3, M.A3, M.E3, M.A3,
        M.F3, M.F3, M.C3, M.F3,
        M.C3, M.C3, M.G3, M.C3,
        M.G3, M.G3, M.D3, M.G3,
      ];
      const stepDur = 0.14;
      const loopDur = melody.length * stepDur;

      const playNote = (freq, t, dur, type = "square", vol = 0.18) => {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        o.type = type;
        o.frequency.setValueAtTime(freq, t);
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(vol, t + 0.008);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        o.connect(g).connect(masterGain);
        o.start(t); o.stop(t + dur + 0.02);
      };
      const playKick = (t) => {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        o.type = "sine";
        o.frequency.setValueAtTime(140, t);
        o.frequency.exponentialRampToValueAtTime(45, t + 0.16);
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(0.45, t + 0.004);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 0.2);
        o.connect(g).connect(masterGain);
        o.start(t); o.stop(t + 0.22);
      };
      let noiseBuf = null;
      const makeNoise = () => {
        if (noiseBuf) return noiseBuf;
        const b = ctx.createBuffer(1, ctx.sampleRate * 0.2, ctx.sampleRate);
        const d = b.getChannelData(0);
        for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
        noiseBuf = b; return b;
      };
      const playSnare = (t) => {
        const src = ctx.createBufferSource(); src.buffer = makeNoise();
        const bp = ctx.createBiquadFilter(); bp.type = "bandpass"; bp.frequency.value = 1800; bp.Q.value = 0.9;
        const g = ctx.createGain();
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(0.32, t + 0.004);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 0.14);
        src.connect(bp).connect(g).connect(masterGain);
        src.start(t); src.stop(t + 0.16);
      };
      const playHat = (t) => {
        const src = ctx.createBufferSource(); src.buffer = makeNoise();
        const hp = ctx.createBiquadFilter(); hp.type = "highpass"; hp.frequency.value = 6500;
        const g = ctx.createGain();
        g.gain.setValueAtTime(0.0001, t);
        g.gain.exponentialRampToValueAtTime(0.10, t + 0.002);
        g.gain.exponentialRampToValueAtTime(0.0001, t + 0.05);
        src.connect(hp).connect(g).connect(masterGain);
        src.start(t); src.stop(t + 0.06);
      };

      const scheduleLoop = (startAt) => {
        for (let i = 0; i < melody.length; i++) {
          const t = startAt + i * stepDur;
          playNote(melody[i], t, stepDur * 0.95, "square", 0.14);
          playNote(melody[i] / 2, t, stepDur * 1.1, "triangle", 0.10);
          if (i % 2 === 0) playNote(bass[(i / 2) % bass.length], t, stepDur * 1.7, "sawtooth", 0.14);
          if (i % 4 === 0) playKick(t);
          if (i % 8 === 4) playSnare(t);
          playHat(t);
        }
      };

      let nextStart = ctx.currentTime + 0.1;
      scheduleLoop(nextStart);
      const tick = () => {
        if (cancelled) return;
        nextStart += loopDur;
        scheduleLoop(nextStart);
        timers.push(setTimeout(tick, loopDur * 1000 - 150));
      };
      timers.push(setTimeout(tick, loopDur * 1000 - 150));
    };

    const onGesture = () => { start(); };
    start();
    window.addEventListener("pointerdown", onGesture);
    window.addEventListener("keydown", onGesture);
    window.addEventListener("touchstart", onGesture, { passive: true });

    return () => {
      cancelled = true;
      window.removeEventListener("pointerdown", onGesture);
      window.removeEventListener("keydown", onGesture);
      window.removeEventListener("touchstart", onGesture);
      timers.forEach(clearTimeout);
      timers = [];
      if (ctx) {
        try {
          if (masterGain) {
            masterGain.gain.cancelScheduledValues(ctx.currentTime);
            masterGain.gain.setValueAtTime(0.0001, ctx.currentTime);
          }
        } catch {}
        setTimeout(() => { try { ctx.close(); } catch {} }, 50);
      }
    };
  }, [enabled]);
}



// =================================================================
// App — header + view router (no bottom nav)
// =================================================================
export default function AdventureCamp() {
  const [view, setView] = useState("levels"); // levels | galaxy | hub | vocab | grammar | speaking | reading | quiz
  const [currentUnit, setCurrentUnit] = useState(1);
  const [cosmicAvatarId, setCosmicAvatarId] = useState("astronaut");


  const [musicOn, setMusicOn] = useState(() => {
    if (typeof window === "undefined") return true;
    return localStorage.getItem("ac_music_on") !== "0";
  });
  useEffect(() => {
    try { localStorage.setItem("ac_music_on", musicOn ? "1" : "0"); } catch {}
  }, [musicOn]);
  useCosmicMusic(musicOn && (view === "levels" || view === "galaxy" || view === "hub"));
  useArcadeMusic(musicOn && (view === "quiz" || view === "grammar"));

  const [coins, setCoins] = useState(0);

  const [streak, setStreak] = useState(0);
  const [name, setName] = useState("");
  const [loading, setLoading] = useState(true);
  const [userId, setUserId] = useState(null);
  const userIdRef = useRef(null);
  const [coinPop, setCoinPop] = useState(false);

  const [owned, setOwned] = useState(() => new Set(FREE_AVATARS));
  const [avatar, setAvatar] = useState("dan");
  const [pickerOpen, setPickerOpen] = useState(false);
  const [confettiBurst, setConfettiBurst] = useState(0);
  const [celebrateName, setCelebrateName] = useState(null);
  const celebrateTimer = useRef(null);

  // warm tts voices
  useEffect(() => {
    if (typeof window === "undefined" || !window.speechSynthesis) return;
    const synth = window.speechSynthesis;
    const warm = () => synth.getVoices();
    warm();
    synth.addEventListener?.("voiceschanged", warm);
    return () => synth.removeEventListener?.("voiceschanged", warm);
  }, []);

  // load profile (coins/streak/name) on mount + auth changes
  useEffect(() => {
    let cancelled = false;
    async function load() {
      const { data: { session } } = await supabase.auth.getSession();
      if (cancelled) return;
      if (!session?.user) { setLoading(false); return; }
      setUserId(session.user.id); userIdRef.current = session.user.id;
      const { data } = await supabase.from("profiles")
        .select("total_coins,streak_days,student_name,avatar_id")
        .eq("id", session.user.id).maybeSingle();
      if (cancelled) return;
      if (data) {
        setCoins(typeof data.total_coins === "number" ? data.total_coins : 0);
        setStreak(typeof data.streak_days === "number" ? data.streak_days : 0);
        setName(data.student_name || "");
        if (data.avatar_id && COSMIC_AVATAR_BY_ID[data.avatar_id]) setCosmicAvatarId(data.avatar_id);
      }
      setLoading(false);
    }
    load();
    const { data: sub } = supabase.auth.onAuthStateChange((e) => {
      if (e === "SIGNED_IN" || e === "USER_UPDATED") { setLoading(true); load(); }
    });
    return () => { cancelled = true; sub.subscription.unsubscribe(); };
  }, []);

  // central addCoins — updates local state + persists to supabase
  async function addCoins(delta) {
    setCoinPop(true);
    setTimeout(() => setCoinPop(false), 450);
    setCoins((c) => {
      const next = Math.max(0, c + delta);
      const uid = userIdRef.current;
      if (uid) {
        supabase.from("profiles").update({ total_coins: next }).eq("id", uid).then(() => {});
      }
      return next;
    });
  }

  function celebrate(n) {
    setConfettiBurst((x) => x + 1);
    setCelebrateName(n);
    clearTimeout(celebrateTimer.current);
    celebrateTimer.current = setTimeout(() => { setConfettiBurst(0); setCelebrateName(null); }, 2200);
  }
  useEffect(() => () => clearTimeout(celebrateTimer.current), []);

  function equipAvatar(id) { setAvatar(id); setPickerOpen(false); }
  function unlockAvatar(id) {
    const z = AVATAR_BY_ID[id];
    if (!z || owned.has(id) || coins < z.cost) return;
    addCoins(-z.cost);
    setOwned((p) => new Set(p).add(id));
    setAvatar(id);
    if (["rare","epic","legendary","mythic"].includes(z.rarity)) celebrate(z.name);
  }

  const currentAvatar = AVATAR_BY_ID[avatar] || ALL_AVATARS[0];

  function back() { setView("hub"); }

  // Profile modal state + name persistence
  const [profileOpen, setProfileOpen] = useState(false);
  const [savingName, setSavingName] = useState(false);
  async function saveProfile(newName, newAvatarId) {
    const uid = userIdRef.current;
    if (!uid) return;
    setSavingName(true);
    const patch = { student_name: newName };
    if (newAvatarId && COSMIC_AVATAR_BY_ID[newAvatarId]) patch.avatar_id = newAvatarId;
    const { error } = await supabase.from("profiles").update(patch).eq("id", uid);
    setSavingName(false);
    if (!error) {
      setName(newName);
      if (newAvatarId) setCosmicAvatarId(newAvatarId);
      setProfileOpen(false);
    }
  }

  return (
    <div className="flex min-h-screen w-full justify-center font-sans gx-shell">
      <style>{STYLES}</style>
      <div className="relative flex h-screen w-full max-w-md flex-col overflow-hidden shadow-2xl gx-shell" style={{ height: "100dvh" }}>
        <StarField count={50} />
        {/* HEADER */}
        <header className="sticky top-0 z-40 shadow-lg">
          <div className="bg-white/95 backdrop-blur">
            <div className="flex items-center justify-center px-4 pb-2 pt-2.5">
              <img src={LOGO_URI} alt="Embassy Language" className="h-9 w-auto select-none" draggable={false} />
            </div>
          </div>
          <div style={{ height: 3, background: `linear-gradient(90deg, #22d3ee, #a78bfa, #ec4899)` }} />
          <div className="relative px-4 pb-3 pt-3" style={{ background: "linear-gradient(135deg,#0b0628 0%, #1e1b4b 60%, #4c1d95 100%)" }}>
            <div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3">
              <div className="flex min-w-0 items-center gap-2.5">
                <button
                  onClick={() => setProfileOpen(true)}
                  className="relative flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-white text-2xl transition-transform hover:scale-105 active:scale-95"
                  style={{ boxShadow: "0 0 0 3px #22d3ee, 0 0 18px #a78bfa" }}
                  aria-label="Open cosmic profile"
                >
                  <span>{COSMIC_AVATAR_BY_ID[cosmicAvatarId]?.emoji || "👨‍🚀"}</span>
                </button>
                <button
                  onClick={() => setProfileOpen(true)}
                  className="min-w-0 text-left leading-tight rounded-lg px-1 transition hover:bg-white/10"
                  aria-label="Edit profile"
                >
                  <p className="truncate text-sm font-extrabold text-white">{name || "Space Cadet"} <span className="text-cyan-300">✎</span></p>
                  <p className="text-[11px] font-bold text-indigo-200">{COSMIC_AVATAR_BY_ID[cosmicAvatarId]?.name || "Astro-Camper"}</p>
                </button>
              </div>
              <div className="flex shrink-0 items-center gap-2">
                <button
                  onClick={() => setMusicOn(v => !v)}
                  aria-label={musicOn ? "Mute music" : "Play music"}
                  title={musicOn ? "Mute music" : "Play music"}
                  className="flex h-9 w-9 items-center justify-center rounded-full bg-white/15 ring-1 ring-white/25 text-white text-base transition hover:scale-110 active:scale-95"
                  style={{ boxShadow: musicOn ? "0 0 12px #22d3ee99" : "none" }}
                >
                  <span>{musicOn ? "🎵" : "🔇"}</span>
                </button>

                <div className={`flex items-center gap-1 rounded-full bg-white px-3 py-1.5 shadow ${coinPop ? "ac-pop" : ""}`}
                  style={{ color: "#1e1b4b" }}>
                  {loading ? <Loader2 size={14} className="animate-spin" /> : <Coins size={14} style={{ color: "#f59e0b" }} />}
                  <span className="text-sm font-black tabular-nums">{loading ? "…" : coins}</span>
                </div>
                <div className="flex items-center gap-1 rounded-full bg-white/15 px-3 py-1.5 ring-1 ring-white/25 text-white">
                  <Flame size={14} className="text-orange-300" />
                  <span className="text-sm font-black tabular-nums">{loading ? "…" : streak}</span>
                </div>
              </div>
            </div>
          </div>
        </header>

        {/* MAIN */}
        <main className="relative flex-1 overflow-y-auto px-3 pb-6 pt-4">
          {view === "levels" && <StarLeague onEnterLevel5={() => setView("galaxy")} />}
          {view === "galaxy" && <UnitGalaxy onEnterUnit={(n) => { setCurrentUnit(n); setView("hub"); }} onBackToLevels={() => setView("levels")} />}
          {view === "hub" && (
            <>
              <button
                onClick={() => setView("galaxy")}
                className="mb-3 inline-flex items-center gap-2 rounded-full gx-glass px-3 py-1.5 text-xs font-black text-white transition hover:scale-105 active:scale-95"
                style={{ boxShadow:"0 0 14px #a78bfa66, inset 0 0 0 1px #a78bfa55" }}
              >
                ☄️ Fly Back to Units
              </button>
              <DashboardHub onPick={setView} name={name} currentUnit={currentUnit} />
            </>
          )}

          {view === "vocab" && (currentUnit === 8 ? <VocabularyQuestU8 onBack={back} addCoins={addCoins} /> : currentUnit === 6 ? <VocabularyQuestU6 onBack={back} addCoins={addCoins} /> : currentUnit === 5 ? <VocabularyQuestU5 onBack={back} addCoins={addCoins} /> : currentUnit === 4 ? <VocabularyQuestU4 onBack={back} addCoins={addCoins} /> : currentUnit === 3 ? <VocabularyQuestU3 onBack={back} addCoins={addCoins} /> : currentUnit === 2 ? <VocabularyQuestU2 onBack={back} addCoins={addCoins} /> : <VocabularyQuest onBack={back} addCoins={addCoins} />)}
          {view === "grammar" && (currentUnit === 8 ? <NebulaGateway onBack={back} addCoins={addCoins} /> : currentUnit === 6 ? <EcoBalancer onBack={back} addCoins={addCoins} /> : currentUnit === 5 ? <QuantumScale onBack={back} addCoins={addCoins} /> : currentUnit === 4 ? <OrbitalAlignment onBack={back} addCoins={addCoins} /> : currentUnit === 3 ? <NebulaBridge onBack={back} addCoins={addCoins} /> : currentUnit === 2 ? <RocketFuelMission onBack={back} addCoins={addCoins} /> : <GrammarLab onBack={back} addCoins={addCoins} />)}
          {view === "speaking" && <CosmicSpeakingNebula onBack={back} addCoins={addCoins} unit={currentUnit} />}
          {view === "reading" && (currentUnit === 8 ? <ReadingAdventureU8 onBack={back} addCoins={addCoins} /> : currentUnit === 6 ? <ReadingAdventureU6 onBack={back} addCoins={addCoins} /> : currentUnit === 5 ? <ReadingAdventureU5 onBack={back} addCoins={addCoins} /> : currentUnit === 4 ? <ReadingAdventureU4 onBack={back} addCoins={addCoins} /> : currentUnit === 3 ? <ReadingAdventureU3 onBack={back} addCoins={addCoins} /> : currentUnit === 2 ? <ReadingAdventureU2 onBack={back} addCoins={addCoins} /> : <ReadingAdventure onBack={back} addCoins={addCoins} />)}
          {view === "quiz" && (currentUnit === 8 ? <Planet5ArenaU8 onBack={back} addCoins={addCoins} /> : currentUnit === 6 ? <Planet5ArenaU6 onBack={back} addCoins={addCoins} /> : currentUnit === 5 ? <Planet5ArenaU5 onBack={back} addCoins={addCoins} /> : currentUnit === 4 ? <Planet5ArenaU4 onBack={back} addCoins={addCoins} /> : currentUnit === 3 ? <Planet5ArenaU3 onBack={back} addCoins={addCoins} /> : currentUnit === 2 ? <Planet5ArenaU2 onBack={back} addCoins={addCoins} /> : <GrandUnitQuiz onBack={back} addCoins={addCoins} />)}
        </main>


        {/* AVATAR PICKER */}
        <AvatarPicker open={pickerOpen} onClose={() => setPickerOpen(false)}
          owned={owned} equipped={avatar} coins={coins}
          onEquip={equipAvatar} onUnlock={unlockAvatar} />

        {/* PROFILE MODAL */}
        <ProfileModal
          open={profileOpen}
          onClose={() => setProfileOpen(false)}
          name={name}
          cosmicAvatarId={cosmicAvatarId}
          onSave={saveProfile}
          saving={savingName}
          avatarEmoji={COSMIC_AVATAR_BY_ID[cosmicAvatarId]?.emoji}
          onOpenAvatar={() => { setProfileOpen(false); setPickerOpen(true); }}
          coins={coins}
          streak={streak}
        />

        <Confetti burst={confettiBurst} />
        {celebrateName && (
          <div className="pointer-events-none fixed inset-x-0 top-24 flex justify-center px-6" style={{ zIndex: 71 }}>
            <div className="ac-banner flex items-center gap-2 rounded-full px-5 py-2.5 text-sm font-extrabold text-white shadow-2xl"
              style={{ background: "linear-gradient(135deg,#22d3ee,#a78bfa,#ec4899)" }}>
              <PartyPopper size={18} /> Unlocked {celebrateName}!
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
